// ============================================================
// Real 3D Scientific Scan of Sheep Astragalus (Ovis aries)
// Centered and scaled for Chuko Royal
// Vertices: 37617, Faces: 75230
// ============================================================
(function(global) {
  'use strict';
  const vB64 = "";
  const fB64 = "";

  function b64ToBuffer(b64) {
    const binStr = atob(b64);
    const len = binStr.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binStr.charCodeAt(i);
    }
    return bytes.buffer;
  }

  global.RealAlchikModel = {
    vertexCount: 37617,
    faceCount: 75230,
    getBufferGeometry: function(THREE_LIB) {
      const T = THREE_LIB || (typeof THREE !== 'undefined' ? THREE : null);
      if (!T) return null;
      const geom = new T.BufferGeometry();
      const posBuf = b64ToBuffer(vB64);
      const idxBuf = b64ToBuffer(fB64);
      geom.setAttribute('position', new T.BufferAttribute(new Float32Array(posBuf), 3));
      geom.setIndex(new T.BufferAttribute(new Uint16Array(idxBuf), 1));
      geom.computeVertexNormals();
      return geom;
    }
  };
})(typeof window !== 'undefined' ? window : globalThis);
